"""Source-assisted reading notes. Ancient quotations are selections, not an OCR transcript."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
if (ROOT/"annotations/remaining.json").exists():
 raise SystemExit("Reviewed annotations already exist; edit annotations/remaining.json directly. This seed script will not overwrite them.")
D = dict(manuscripts=[], slips=[], images=[])
def source(label, url, **kw): return dict(label=label,url=url,**kw)
BOOK=source('《竹简上的经典——清华简文献展》原文58、图版59、释文60页','https://www.tup.tsinghua.edu.cn/upload/books/yz/071131-01.pdf#page=58')
YIN=source('复旦读书会《尹至》《尹诰》研读札记：逐简释文','https://www.fdgwz.org.cn/Web/Show/1352')
YIN2=source('张崇礼《清华简〈尹诰〉考释》：异读讨论','https://www.fdgwz.org.cn/Web/Show/2400')
XI=source('小狐《读〈系年〉臆札》附逐简通行释文（研究者校读）','https://www.fdgwz.org.cn/Web/Show/1766')
SH=source('清华大学第八辑发布：原简及旁附释文','https://www.tsinghua.edu.cn/info/1177/22545.htm')
SH2=source('程浩《清华简〈摄命〉的性质与结构》','https://www.ctwx.tsinghua.edu.cn/__local/1/0A/90/4E2D23E39E024B3DA5FBD0EDCD7_E8A8D0EF_3BA0A.pdf?e=.pdf')
AD=source('清华大学第九辑发布：成人篇的法制内容','https://www.tsinghua.edu.cn/info/1173/17467.htm')
WU=source('简帛网《五纪》初读第33页：拆分字形与逐简读法（研读讨论，非定本）','https://www.bsm.org.cn/forum/forum.php?mod=viewthread&page=33&tid=12694')
WU2=source('清华大学出土文献中心：五纪、五音图介绍及整理者访谈','https://www.ctwx.tsinghua.edu.cn/info/1072/3113.htm')
LI=source('王晓华《清华大学藏战国竹简（拾肆）读记（一）》','https://www.fdgwz.org.cn/Web/Show/11228')
LI2=source('文汇报：清华大学供图的两中简1、2及旁附释文','https://www.whb.cn/commonDetail/962078')
MA=source('贾连翔《清华简中的先秦养马知识》：整理者说明','https://export.shobserver.com/baijiahao/html/1065122.html')
MA2=source('简帛网《胥马》初读：简29尚有争议的字词','https://www.bsm.org.cn/forum/forum.php?mod=viewthread&tid=15825')
def manuscript(name,summary,context,sources):
 D['manuscripts'].append(dict(name=name,summary=summary,context=context,sources=sources))
def slip(name,n,reading,explanation,terms=(),uncertainties=(),sources=(),basis=None,observation=None):
 key=f'{name}-{n:03}'
 D['slips'].append(dict(key=key,manuscript=name,number=n,reading=reading,reading_basis=basis or '据所列来源的逐简释文转为通行字，并参看照片；以下是选读，省略号不代表原简一定残缺。',visual_observation=observation or '以图版标注的现代整理简号定位；释文不是单靠这张照片独立识出的结果。',explanation=explanation,terms=[dict(term=t,meaning=m) for t,m in terms],uncertainties=list(uncertainties),sources=list(sources)))
 return key
def img(id,keys,observation,status='来源辅助识读',limitations=()):
 D['images'].append(dict(id=id,slip_keys=keys,observation=observation,status=status,limitations=list(limitations)))

manuscript('封许之命','周王命吕丁为许侯，并赐给礼器、车马、服饰，要求他继续辅佐周室。','所用展览书保留简1—9的编号位置，1、4缺简；照片中实际只有简2、3、5、6、7、8、9。文献是周初分封许国的册命，具体王世仍属研究问题。',[BOOK])
feng=[
 (2,'……越在天下，故天劝之亡斁，尚纯厥德，膺受大命，骏尹四方。则惟汝吕丁，肇右文王，毖光厥烈……','承接缺失的开头，先说明有德者受天命，再称赞吕丁辅佐文王的功绩。册命先追述旧功，为后面授予许侯地位作铺垫。',[('亡斁','无厌倦、不止息。'),('右','这里通“佑”，辅佐。'),('骏尹四方','大大治理四方；尹作治理解。')]),
 (3,'□司明刑，厘厥猷，祗事上帝。桓桓丕敬，严将天命。亦惟汝吕丁，扞辅武王，干敦殷受，咸成商邑……','继续称颂吕丁敬奉天命、辅佐武王攻商的功绩。殷受是商王受，也就是通常所说的商纣王；读到“商邑”后，后面的衔接因简4缺失而中断。',[('猷','谋划、施政方略。'),('祗','敬慎。'),('扞辅','捍卫并辅佐。')]),
 (5,'命汝侯于许。汝惟臧耆尔猷，虔恤王家，简乂四方不□，以勤余一人。锡汝苍圭、秬鬯一卣……','核心命令是“让你在许地为侯”。受封不是只得土地与礼物，也要慎重谋政、操心王室、协助天子治理。后面开始列赐物。',[('锡','赐予。'),('秬鬯','祭祀用的香酒。'),('卣','盛酒的器具。'),('余一人','周王对自己的称呼。')]),
 (6,'……鸾铃素旗，朱筓。马四匹……罗缨，钩膺，纂弁……赠尔荐彝……','这一简主要列车马和马具、服饰等赐物，并转入宗庙祭器。四匹马与车乘配套；一长串专名是在记录身份、礼仪与军事资源。',[('鸾铃','车马上的铃饰。'),('钩膺','马胸前的带饰。'),('彝','这里泛指礼仪祭器。')]),
 (7,'……龙鬹、琏、鑵、钲……盘、鉴、蓥……鼎、簋、觥、卣、格。王曰：“呜呼，丁，戒哉！余既监于殷……','前半继续开列礼器，后半改为周王直接训告：吕丁要警戒，以殷商的败亡为鉴。礼器专名有难字，不据模糊的字形逐件强定用途。',[('监','借鉴。'),('鼎、簋','典型的食器、礼器名称。'),('戒哉','要警惕、谨慎。')]),
 (8,'之不若，……靡念非常，汝亦惟淑章尔虑，祗敬尔猷，以永厚周邦，勿废朕命，经嗣……','承上简“殷之不若”：周王把殷商的失政作为警示，要求受命者周密思虑、敬慎行事、巩固周邦，不废弃王命。末尾要接简9才成句。',[('不若','不善、不顺。'),('勿废朕命','不要废弃我的命令。')]),
 (9,'世享。','本简仅接上简末尾“经嗣”，合读为“经嗣世享”。大意是希望后嗣世代延续享有其封国、祭祀与受命地位。大片空白是篇末书写状态，不能填入想象的缺文。',[('世享','世代享有、奉享。')])]
fk=[]
for n,r,e,t in feng:
 fk.append(slip('封许之命',n,r,e,t,['引文为选读；未收录字词以……省去，□表示据本次采用释文仍不确释的字。','简1、4缺失，不能补写出一篇无缺口的诏命。'],[BOOK],observation='已核对原书58页逐简排印与59页照片的编号及分界；依60页释文作通行字选读。'))
img('pdf-p059-Im0',fk,'实际排列七支简，编号为2、3、5、6、7、8、9；原图没有把缺失的1、4补上。',limitations=['此前“第1–9简”仅是编号范围，现更正实际保存与展示范围。'])
img('museum-02',fk,'馆方展示同篇的简册，读字请与出版社清晰图版对照。',limitations=['网页图分辨率有限，所附读法依出版释文。'])
for id,n in [('pdf-p059-Im1',2),('pdf-p059-Im2',6),('pdf-p059-Im3',7)]:
 img(id,[f'封许之命-{n:03}'],f'这是简{n}的局部放大，便于观察笔画与竹材；下面列出的释文范围比这个局部大。',limitations=['局部没有显示全简文字，不能把下列选读全部说成在此图中可见。'])

manuscript('尹诰','伊尹与商汤讨论夏为何失去民心，以及新政权如何安定民众。','馆方图为四支简。以复旦读书会逐简释文定位；“夏自□其有民”“我克协我友”“金玉日邑”等有不同释读，下文保留争议。',[YIN,YIN2])
yr=[
 (1,'唯尹既及汤咸有一德，尹念天之败西邑夏，曰：“夏自□其有民，亦惟厥众，非民无与守邑。”','开头把伊尹与汤联系起来，继而讨论夏的败亡。最后一句较明确：没有民众，就没有人共同守住城邑，强调统治要依靠民众。',[('尹、挚','在篇中指伊尹；挚是其名。'),('一德','同心同德或德行一致；全句结构仍有讨论。')],['“夏自□”原字有绝、幻、捐等读法，本次不选择一个异读作为定论。','“既及汤咸有一德”的句法、“厥众”是否读为蹶众均有争议。']),
 (2,'厥辟作怨于民，民复之，用离心，我翦灭夏。今后曷不监？挚告汤曰：“我克协我友。今……”','这段将夏亡解释为君主使民众怨恨，君民因而离心，并劝新君引以为鉴。后面的“我克协我友”进入如何团结与治理的讨论，句子跨到简3。',[('辟','君主。'),('曷不监','为何不引以为鉴。'),('翦灭','消灭、剪除。')],['“复之，用离心”的断句、“我克协我友”的主语及语气有不同意见。']),
 (3,'惟民远邦归志。汤曰：“呜呼！吾何作于民，俾我众勿违朕言？”挚曰：“后其赉之，其有夏之……”','商汤问：怎样对待民众，才能使大家不背离自己的号令？伊尹的答语涉及“赉”（给予），具体给予什么，要接下一简并结合不同句读判断。',[('俾','使、让。'),('赉','给予、赏赐；该字亦有理等异读。')],['“今惟民远邦归志”与上简如何断句有异说。']),
 (4,'金玉日〔读法有争议〕邑，舍之吉言。”乃致众于亳中邑。','最后涉及夏的金玉、邑与“吉言”，继而把民众召集或迁致亳邑。“日”若读牣，是充满之义；若释为田，则会导向金玉与田邑的解释，因此暂不给这一句唯一的白话全译。结尾行动本身可说明政权重建与聚民有关。',[('亳','与商汤相关的都邑名称。'),('致众','招致、召集民众。')],['“日”有实、牣、田等读法，直接影响财富与邑的关系。','“舍之吉言”的舍与吉言也有训释分歧。'])]
yk=[slip('尹诰',n,r,e,t,u,[YIN,YIN2],observation='馆方小图可以核对四支的排列和简号，字形像素不足，文字主要依据有简号的学术释文。') for n,r,e,t,u in yr]
img('museum-07',yk,'由右至左简1—4；前三支较密，末支文字较少。','小图＋来源辅助识读',['不能从450像素宽的概览独立核实每个古文字。'])

manuscript('系年','这张图展示开篇三章：周王朝兴衰、幽王至平王的更替与诸侯局势、秦人先世。','图中“第一章、第二章、第三章”及简号可定位为1—16；中间第8简另列细长摹写/辅助图，并不是多出一支正文简。以研究者所附逐简通行释文选读。文献的叙事与《史记》等有差异，不把每一细节直接当作无争议的历史事实。',[XI])
xir=[
(1,'昔周武王监观商王之不恭上帝……乃作帝籍，以登祀上帝天神……','以祭祀失敬解释商王的政治问题，并叙述周武王设置帝籍。帝籍通常联系天子用于祭祀的籍田；“籍”具体字形及句读有讨论。'),
(2,'千亩，以克反商邑，敷政天下。至于厉王，厉王大虐于周……','承上简命名“千亩”，随后叙述周取代商、推行政令；再跳到厉王的暴政以及各阶层不满。'),
(3,'乃归厉王于彘，共伯和立……宣王即位，共伯和归于宋〔宗〕……','叙述厉王被逐、共伯和执政与宣王继立。宋字究竟是地名还是读为宗等，需要保留不同解释。'),
(4,'……立卅又九年，戎乃大败周师于千亩。','第一章以宣王时周军在千亩败于戎收束；中间弃帝籍、弗畋等字句的释读影响作者所说的失政原因。'),
(5,'周幽王取妻于西申，生平王……褒姒，生伯盘。褒姒嬖于王……','交代幽王婚姻、平王与伯盘的不同母系，作为王位冲突的背景。'),
(6,'与伯盘逐平王，平王走西申。幽王起师，围平王于西申，申人弗畀……','叙述平王被逐后逃往母族西申；幽王用兵索取平王，申人拒绝交出。'),
(7,'攻幽王，幽王及伯盘乃灭，周乃亡……是携惠王。','叙述外部军事介入导致幽王与伯盘覆亡，随后另立余臣为携惠王。“周乃亡”在此指该次王朝危机，不是说周这个国号从此彻底不存在。'),
(8,'立廿又一年，晋文侯仇乃杀惠王于虢。周无王九年……','这里的二十一年、无王九年及惠王之死，构成与传世叙事不同的时间线；它是文本中的说法，年代关系有研究争论。'),
(9,'晋文侯乃逆平王于少鄂，立之于京师。三年，乃东徙，止于成周……','记晋文侯迎立平王，并叙述三年后迁往成周。“逆”在这里是迎接，不能读成忤逆。'),
(10,'……郑武公亦正东方之诸侯。武公即世，庄公即位；庄公即世，昭公即位。','由周室东迁转入郑国的兴起和国君更替。“即世”是去世，“即位”是继位。'),
(11,'其大夫高之渠弥杀昭公而立其弟子眉寿。齐襄公会诸侯于首止……','叙述郑国内部弑君和改立，以及齐襄公介入诸侯政治。人名在不同典籍中可能有不同写法。'),
(12,'……车轘高之渠弥，改立厉公……楚文王以启于汉阳。','前半续郑国变乱后的处理，后半以楚在汉水以北地区的扩张作衔接；这是一段压缩的历史梗概。'),
(13,'周武王既克殷，乃设三监于殷。武王陟，商邑兴反……','第三章重新回到武王克商之后，讲设置三监以及武王去世后商地发生反叛。陟在此是王逝世的委婉说法。'),
(14,'……飞廉东逃于商盖氏，成王伐商盖，杀飞廉，西迁商……','叙述成王平叛、飞廉逃亡及对相关人群的迁徙；“商盖”通常与传世商奄相联系，但用字、地名解释仍须分别处理。'),
(15,'盖之民于朱圉，以御奴虘之戎，是秦之先……平王东迁……','把迁到朱圉、防御戎人的这批人称为秦的祖先。这是研究秦人起源的重要古代叙事，不能只凭一句就解决全部族源问题。'),
(16,'周，秦仲焉东居周地，以守周之坟墓，秦以始大。','续上简“成周”，继而说秦进入周的旧地、守护王室坟墓并开始壮大。秦仲所指与事件年代的对应仍有讨论。')]
xk=[slip('系年',n,r,e,(),['选录可定位的语句；“……”省去的部分没有尝试补成全文。','小图不足以独立逐字验证；采用的研究者释文亦有异读。'],[XI],observation='据馆方图的章名和下方整理简号定位；文字主要依学术校读而非本图OCR。') for n,r,e in xir]
img('museum-06',xk,'三个区块分别标第一、第二、第三章，可对到简1—4、5—12、13—16；第8简旁有辅助显示。','小图＋来源辅助识读',['概览的字宽只有数像素，完整古文字笔画不可独立核验。','第一章到第三章是一张选图，不等于全篇138简。'])

manuscript('摄命','周王向伯摄发布任命与训诫，要求受命者分担治理责任。','右侧把最前两支简分段放大，左侧是全篇概览。篇中周王与伯摄的历史身份有不同主张，不能简单断言就是某王的原始档案。',[SH,SH2])
sk=[slip('摄命',1,'王曰……余一人无昼夕……','王以“王曰”开始发言，谈自己的忧虑与为政负担；“余一人”是王自称，昼夕指日夜。这为选任辅臣、分担政事作铺垫。',[('余一人','王自称。')],['开头称谓及毖、摄等字的句读较复杂，只选录能与旁附释文核对的短语。'],[SH,SH2],observation='右侧最右一组为简1的分段放大，旁有现代排印释文。'),slip('摄命',2,'……余亦横于四方……','承接王的忧思，谈面向四方的治理。“横”这里不按现代“横行霸道”解释；整段属于王自陈责任和忧患的诰命语体。',(),['这里只能谨慎选读；不把照片中尚未核清的字补成流畅全文。'],[SH,SH2],observation='右侧左一组是续简的分段图；与旁列简1、全篇首部顺序对照识别为简2。')]
img('release-01',sk,'左侧32简概览；右侧为最前两支分段放大。','局部选读',['总览区域不能逐字读；本次仅给放大部分的选读，不对其余30支制造释文。'])

manuscript('成人','王与“成人”问答，讨论用法、断狱和司法人员应有的态度。','这里的“成人”是篇中的称谓，不能按现代成年人的日常含义解释。整理团队说明本篇涉及听取原被告陈述、查证细节和审断案件。',[AD])
img('release-02',[],'多支简紧密排列的整组展示图；单字像素很少，不能可靠辨全篇字形。','仅能作篇级解释',['未获得可逐字核对的放大图与配套逐简释文；暂不填写逐简读法。','可解释篇章主题，但不能把新闻介绍倒写成图中的原文。'])

manuscript('五纪','将日月星辰、德行、神祇与人体组织成对应体系，并含黄帝、蚩尤的神话叙事。','本图仅九支选简：25、26、79—82、109—111。采用简帛网研读讨论的分简文字作线索，再对照照片中的重复结构选读；涉及疑难字的整理尚不能视为定本。神祇与身体的对应属于古人的宇宙观，不是现代解剖或自然科学结论。',[WU,WU2])
wr=[
(25,'……后曰：礼、义、爱、仁、忠……建星、牵牛、婺女、虚、危、营室……奎、娄、胃、昴……','将德行与星象的秩序连在一起，并逐一列星名。这里的星名体系与后来的二十八宿有联系，但名单与表达并不完全相同，不宜强行逐字换成后世标准名。',[('牵牛、婺女','古代星名。')],['“六德合五建”等语及若干星名仍有不同释读。']),
(26,'……参、伐；狼、弧、咮、张……大角、天根、本角、驷、心……箕。神尚南门，后正北斗。后曰：天地、四荒、四冘……','续列星名，再把神、王与南门、北斗建立对应，最后转向天地诸神的分类。这支同时跨了两段，所以不能把整支都当成同一份星宿表。',[('后','此语境中的统治者称呼，不是“后面”。'),('北斗','星象体系中的重要定位。')],['“尚”“正”及四冘等字词的具体解释仍有讨论。']),
(79,'……后事咸成，万生行象则之。天为首，地与四……','进入以身体组织宇宙的叙述：首先以天对应头部，随后继续到地、四荒等。句尾“地与四”需接简80才能读完。',[('首','头。'),('象则','效法、取作法则。')],['开头承接简78；不能把本段开头误当成整简开头。']),
(80,'荒与行、明星、颛顼、司盟为脊，甲子之旬是司。高大、大川、大山与月……及……','把地与诸神等对应脊背，并用甲子旬为其时间秩序；随后列出下一组神祇，句意继续跨入简81。',[('脊','脊背。'),('旬','十日；甲子旬是以甲子开始的一组十日。')],['神名“高大”等不能直接套作现代普通形容词；部分神名字形未确释。']),
(81,'门为右胁，甲戌之旬是司。大音、大石、稷匿与日……为左胁。','将两组神祇分别对应身体右胁与左胁，并配不同的旬。读法显示它是对应表式的知识，而不是普通叙事。',[('胁','身体两侧、肋部。')],['省去处多为神名；省略不是断简。']),
(82,'甲申之旬是司。南冘右肩，东冘左肩；北冘左髀，西冘右髀。西柱右肱，东柱左肱；西柱右股……','继续按方位、左右、身体部位安排神祇：肩、髀、肱、股依次出现。可以看到以人体作宇宙秩序缩影的思考方式。',[('髀','股部、髋股一带，古义范围需结合语境。'),('肱','上臂。'),('股','大腿。')],['神名“冘”暂保留字形，未强定为另一个常用字。']),
(109,'始祀高畏、畏溥、四荒……黄帝既杀蚩尤，乃飨蚩尤之躬，焉始为……','前半续黄帝设祭的叙述，后半进入黄帝战胜蚩尤并处理其身体的神话。这里可讨论古人如何解释祭祀与物类的起源，不能当作亲历战争记录。',[('飨','与享祭、宴享有关；此处要连同祭祀语境理解。')],['高畏、畏溥等名号及“配帝身”的读法有讨论。']),
(110,'……以其发为韭，以其眉须为蓼……以其鼻为葱……以其从〔爪〕……','按平行句“以其X为Y”，把蚩尤身体部位与植物等事物联系起来，例如头发与韭、鼻与葱。这是身体化生的神话表达。',[('发','头发。'),('须','胡须。')],['开头“五芒”等字及部分物名存在异读，不据选图定其唯一含义。']),
(111,'为蒜。以其骸为干侯股，以其臂为桴……为鼓……凡其身为天畏忌……','先接上一简“以其爪为蒜”，再把身体部位与射侯支架、鼓槌、鼓等用具联系起来；仍属于神话中的起源叙事。',[('桴','鼓槌。'),('侯','可指射礼所用的标靶，相关器物词需继续校释。')],['干侯股、肛（腔？胸？）、天畏忌等词的字形与词义未完全确定，因此只解释明确的句式与主题。'])]
wk=[slip('五纪',n,r,e,t,u,[WU,WU2],basis='研读讨论辅助的暂定选读：只选字形、分简与重复句式较能对照的片段；不能代替正式校勘定本。',observation='照片下方简号清楚；已核对本组位置、重复句式及若干数字/身体词的字形。') for n,r,e,t,u in wr]
img('release-04',wk,'从右到左依次25、26、79、80、81、82、109、110、111。后两支“以其…为…”反复出现；中组可见左右与身体部位的成对表达。','研读讨论辅助选读',['图有九支，编号不连续；不能把25直接接到79。','引文和释义中的异读已标出，尚未完成严格的逐字隶定。'])

manuscript('五音图','图中央以五角星式线条组织宫、商、角、徵、羽的生成关系。','这是一幅跨多支竹简绘写的图，读序不能简单规定为每支从上到下。整理者将图中的五音生成与三分损益法联系起来：用长度的三分之一增减关系安排音律，而非按今天的五线谱直接演奏。',[WU2])
img('release-03',[],'可见中央交叉的五角星线条、沿图线分布的字与大量残断；下沿现代编号标示其拼接位置。','图形识别与篇级解释',['没有把每一根线、每个字与对应简号逐项校定。','现图用于说明五音相生；不能凭图补出具体古曲或认作现代乐谱。'])

manuscript('两中','圭中、祥中向夏启讲述天命、德行与治理，带有神话和政治论说的性质。','样张是简1、2，每支又分三段展示。开头“夏后奠卣”的解释有争议：治水、居丧、制度秩序等说法会改变句意，本次不强定其中一说。',[LI,LI2])
lk=[slip('两中',1,'夏后奠卣，庶灵因固，九德溥扬。两中乃入，格于有河。三年，在日乙丑，两中或……','先陈述夏后与众神秩序、九德的关系，再引出“两中”到有河，以及三年乙丑日的时间节点。“夏后奠卣”难以给唯一译法；后面的事件框架相对清楚。',[('两中','圭中、祥中两位角色的合称。'),('乙丑','干支纪日。'),('有河','此处为叙事中的名称，不据字面译成“有一条河”。')],['奠卣有多种读解，夏后具体所指也有研究分歧。','溥、敷等读法及格于有河的解释有异说。'],[LI,LI2],basis='按新闻图旁附释文及首句研究作选读，保留争议字“奠卣”。',observation='右边三段合为简1；不是三支独立竹简。'),slip('两中',2,'〔接上简〕……于有夏……天……后……亥……三日……','本简续写“两中”与有夏的交往。旁附释文包含多个人名或神名和难字，本次只列能谨慎对照的零星文字；无法据此可靠重构整句意思。',[('有夏','夏的称谓，不能机械拆成“拥有夏天”。')],['这里没有提供完整白话译文：人名、语法关系及个别字仍未核清。','所列省略号覆盖未确释部分，不表示照片有同样长度的物理缺口。'],[LI2],basis='仅作局部字词尝试；本简未达到可靠的整句识读。',observation='左边三段合为简2，可见接缀处；需按同一支简的分段顺序复原。')]
img('release-05',lk,'两支简各切成三段排版，并附现代隶定小字；左边还有图书封面，不是额外简影。','简1来源辅助、简2未确释',['不把疑难字改写成顺畅但无依据的故事。'])

manuscript('胥马','相马知识：通过马的种属、体形、大小、肥瘦与毛色，判断其速度、力量和耐力。','整理者说明“胥”是观察。全篇有“胥属，胥形，胥长，胥肉，胥色”的原则；这句话作为全篇背景引述，尚未确认就写在本图28—31简中。',[MA])
mk=[]
for n,obs,r,e in [
(28,'图中最右支，长行文字较密。','〔未可靠释出完整句〕','本简处于相马条则的篇内，但尚未取得与照片逐字对应的可靠全文。可以确认篇类，不据全文概述反推本简细节。'),
(29,'右起第二支，需接前后简理解相马术语。','研究讨论引作：“务之乃止，小胸亦止，是谓〔争议字〕閟。”','若暂从这一读法，片段涉及马胸等特征及其评价；其中关键字仍有争议，不能把术语强译成现代马匹疾病或性能结论。'),
(30,'右起第三支，数处重复式文字可比较笔画。','〔未可靠释出完整句〕','本次只确认其图版位置。重复用字应结合相马术语校读，不能仅凭形似就替换成现代熟字。'),
(31,'最左支，文字在上半部，后半留白，简体可见断裂接合。','〔未可靠释出完整句〕','书写短句反复、末段留白，可以说明本段条则的版式；这些形态信息尚不足以解释每句具体如何判马。')]:
 mk.append(slip('胥马',n,r,e,(),['本简仍待正式逐简释文或更清晰字形核对；不宣称已完成释读。'],[MA,MA2] if n==29 else [MA],basis='局部识别尝试未完成；简29仅列研究讨论提出的读法，并标明其争议。',observation=obs))
img('release-06',mk,'由右到左为简28—31，末支留白明显，完整可核对编号。','逐简尝试，尚未确释',['图片虽长，专业马体词和异体字仍造成困难。','篇章背景可解释，四简的严格隶定与逐句翻译尚不能可靠完成。'])

